mapper.select:
SELECT COUNT(*)
  FROM TB_AM02M01 M
 WHERE 1 = 1

   AND M.CO_CD = #{coCd, jdbcType=VARCHAR}


   AND M.FORM_CAT = #{formCat}


   AND M.USE_YN = #{useYn}


   AND (M.FORM_CD LIKE '%' || #{searchValue} || '%' OR M.FORM_NM LIKE '%' || #{searchValue} || '%')

SELECT * FROM ( SELECT ROWNUM AS RN, A.* FROM ( SELECT M.FORM_CD, M.FORM_NM, M.FORM_CAT, FN_CM05M01_CD_TO_NM(M.FORM_CAT) AS FORM_CAT_NM, M.FORM_DESC, M.CURR_VER, M.USE_YN, M.SORT_NO, M.CO_CD, FN_CM05M01_CD_TO_NM(M.CO_CD) AS CO_NM, TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD') AS CREAT_DTTM FROM TB_AM02M01 M WHERE 1 = 1
AND M.CO_CD = #{coCd, jdbcType=VARCHAR}
AND M.FORM_CAT = #{formCat}
AND M.USE_YN = #{useYn}
AND (M.FORM_CD LIKE '%' || #{searchValue} || '%' OR M.FORM_NM LIKE '%' || #{searchValue} || '%')
ORDER BY M.SORT_NO ASC, M.FORM_CD ASC ) A WHERE ROWNUM <= #{lastIndex} ) WHERE RN >= #{firstIndex}
